      if (b.loan && b.loan.memberId === memberId) return { ok: false };
      if (b.holds.some(h => h.memberId === memberId)) return { ok: false };
      b.holds.push({ memberId, readyUntil: null });
      return { ok: true, position: b.holds.length };
